// loft: circles of radius 10 at z = 0 and 5 at z = 30, lofted along the straight line between their centres (3 sections)
export function c006(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(s1, "c1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(s1);
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 30) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(s2, "c1", { "center" : vector(0, 0) * millimeter, "radius" : 5 * millimeter });
    skSolve(s2);
    const path = newSketchOnPlane(context, id + "path", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(path, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(30, 0) * millimeter });
    skSolve(path);
    loft(context, id + "loft1", { "sheetProfilesArray" : [{ "sheetProfileEntities" : qSketchRegion(id + "s1") }, { "sheetProfileEntities" : qSketchRegion(id + "s2") }], "addSections" : true, "spine" : qCreatedBy(id + "path", EntityType.EDGE), "sectionCount" : 3 });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID)) };
}

